package e.e.a;
import java.util.*;
public class SeriesQueueTest {
 public static class Player {int repeat;long position=123;boolean started;public void setRepeatMode(int v){repeat=v;}public void seekTo(long p){position=p;}public void start(){started=true;}}
 public static class Fragment {public ArrayList<?> C1;public int D1;public boolean U0,F0=true;public Player a0=new Player();}
 static int checks;static void check(boolean v,String m){checks++;if(!v)throw new AssertionError(m);}
 public static void main(String[] args)throws Exception{java.lang.reflect.Method bind=SeriesPlayback.class.getDeclaredMethod("bind",Object.class,ArrayList.class,int.class);bind.setAccessible(true);ArrayList<String> rows=new ArrayList<>(Arrays.asList("sm1","sm2","sm3"));Fragment f=new Fragment();bind.invoke(null,f,rows,1);check(f.U0&&f.C1==rows&&f.D1==1,"ON installs the current queue");check(!f.F0&&f.a0.repeat==0,"initial continuous play and repeat state agree");SeriesPlayback.toggleRepeat(f);check(f.F0&&f.a0.repeat==1&&f.U0,"repeat can be enabled during continuous play");check(SeriesPlayback.repeatCompletion(f)&&f.a0.position==0&&f.a0.started&&f.D1==1,"repeat completion restarts current video without advancing queue");SeriesPlayback.prepared(f);check(f.a0.repeat==1,"re-preparing media retains the explicit repeat choice");SeriesPlayback.toggleRepeat(f);check(!f.F0&&f.a0.repeat==0&&!SeriesPlayback.repeatCompletion(f),"repeat OFF returns completion to queue navigation");bind.invoke(null,f,null,0);check(!f.U0&&f.C1==null&&!f.F0,"OFF retains an explicit user repeat change");Fragment original=new Fragment();bind.invoke(null,original,rows,1);bind.invoke(null,original,null,0);check(original.F0&&original.a0.repeat==1,"untouched repeat preference restored when disabling series");Fragment nativeQueue=new Fragment();nativeQueue.U0=true;nativeQueue.C1=rows;SeriesPlayback.prepared(nativeQueue);check(!nativeQueue.F0&&nativeQueue.a0.repeat==0,"a native list queue begins with repeat off");SeriesPlayback.toggleRepeat(nativeQueue);check(nativeQueue.F0&&nativeQueue.a0.repeat==1,"native list queue allows repeat controls");bind.invoke(null,f,new ArrayList<>(),0);check(!f.U0,"empty queue cannot enable navigation");bind.invoke(null,f,rows,-1);check(!f.U0,"invalid current index cannot enable navigation");System.out.println("Series queue/repeat: "+checks+" checks passed");}
}
